cat tests/basics/try_finally_return{,2,3,4,5}.py; grep -n 'stack_size\|adjust_stack\|setup_block\|end_finally' py/emitnative.c py/emitbc.c py/emit.h | head -120; ports/unix/build-standard/micropython -c $'class IDGenerator:
 def __init__(self, max_id):
  self._i = 0
  self._mi = max_id
 def get(self):
  try:
   return self._i
  finally:
   self._i += 1
   if self._i > self._mi:
    self._i = 0
id_gen = IDGenerator(10)
print(id_gen.get())'

patch -p1 <<'PATCH'
--- a/py/compile.c
+++ b/py/compile.c
@@ -1672,19 +1672,19 @@
 STATIC void compile_try_finally(compiler_t *comp, mp_parse_node_t pn_body, int n_except, mp_parse_node_t *pn_except, mp_parse_node_t pn_else, mp_parse_node_t pn_finally) {
     uint l_finally_block = comp_next_label(comp);

     compile_increase_except_level(comp, l_finally_block, MP_EMIT_SETUP_BLOCK_FINALLY);
+    EMIT_ARG(adjust_stack_size, 3); // stack adjust for possible UNWIND_JUMP state

     if (n_except == 0) {
         assert(MP_PARSE_NODE_IS_NULL(pn_else));
-        EMIT_ARG(adjust_stack_size, 3); // stack adjust for possible UNWIND_JUMP state
         compile_node(comp, pn_body);
-        EMIT_ARG(adjust_stack_size, -3);
     } else {
         compile_try_except(comp, pn_body, n_except, pn_except, pn_else);
     }
     EMIT_ARG(load_const_tok, MP_TOKEN_KW_NONE);
     EMIT_ARG(label_assign, l_finally_block);
     compile_node(comp, pn_finally);

     compile_decrease_except_level(comp);
+    EMIT_ARG(adjust_stack_size, -3);
 }
PATCH
source tools/ci.sh && ci_unix_build_helper VARIANT=standard > /tmp/micropython-finally-build.log 2>&1 && tail -12 /tmp/micropython-finally-build.log

